-- Qualify the source curriculum argument so it cannot collide with column names.
create or replace function public.e3_copy_class_curriculum(requested_class_id uuid,source_curriculum_id uuid,new_name text default null)
returns uuid language plpgsql security definer set search_path=public as $$declare result uuid;source public.curricula%rowtype;next_count integer;milestone integer;begin if not exists(select 1 from public.classes c where c.class_id=$1 and (c.teacher_user_id=auth.uid() or public.e3_is_developer())) then raise exception 'Class not found or access denied';end if;select c.* into source from public.curricula c where c.curriculum_id=$2 and (c.owner_user_id=auth.uid() or c.is_public or public.e3_is_developer());if source.curriculum_id is null then raise exception 'Source curriculum not found or access denied';end if;insert into public.curricula(owner_user_id,name,grade_level,subject,description,source_document_url,source_curriculum_id,is_public,is_template) values(auth.uid(),coalesce(nullif(trim(new_name),''),source.name||' Copy'),source.grade_level,source.subject,source.description,source.source_document_url,source.curriculum_id,false,false) returning curriculum_id into result;insert into public.curriculum_members(curriculum_id,user_id,role) values(result,auth.uid(),'owner');insert into public.lesson_records(curriculum_id,lesson_code,title,unit_name,chapter_name,sort_order,status,estimated_periods,mission_position,presentation_url,guide_url,assignment_links,notebook_links,resource_links,prep_materials,teacher_notes,assignments,notebook_pages,lesson_notes) select result,l.lesson_code,l.title,l.unit_name,l.chapter_name,l.sort_order,l.status,l.estimated_periods,l.mission_position,l.presentation_url,l.guide_url,l.assignment_links,l.notebook_links,l.resource_links,l.prep_materials,l.teacher_notes,l.assignments,l.notebook_pages,l.lesson_notes from public.lesson_records l where l.curriculum_id=$2;update public.classes c set curriculum_id=result where c.class_id=$1;update public.curricula c set copy_count=c.copy_count+1 where c.curriculum_id=source.curriculum_id returning c.copy_count into next_count;foreach milestone in array array[1,5,10,20,50,100,200,500,1000] loop if next_count>=milestone and next_count-1<milestone then insert into public.teacher_achievements(user_id,achievement_key,title,detail,metal) values(source.owner_user_id,'curriculum-copies:'||milestone,case when milestone=1 then 'First Curriculum Copy' else milestone||' Curriculum Copies' end,'Teachers have copied your curriculum '||milestone||case when milestone=1 then ' time.' else ' times.' end,case when milestone>=20 then 'gold' else 'silver' end) on conflict(user_id,achievement_key) do nothing;end if;end loop;return result;end;$$;
notify pgrst,'reload schema';
